WITH RECURSIVE tree AS (SELECT id,parent_id,name,node_type,metadata,1 AS depth FROM public.drive_nodes WHERE parent_id IS NULL AND name='SAMPLE — 00_Automotive_Hardware_Audit_Repository' AND is_trashed=false UNION ALL SELECT n.id,n.parent_id,n.name,n.node_type,n.metadata,t.depth+1 FROM public.drive_nodes n JOIN tree t ON n.parent_id=t.id WHERE n.is_trashed=false) SELECT depth,node_type,count(*) FROM tree GROUP BY depth,node_type ORDER BY depth,node_type;